{
  "jsonrpc": "2.0",
  "id": 2,
  "method": "tools/call",
  "params": {
    "name": "api_execute",
    "arguments": {
      "service": "product",
      "code": "async () => { const r = await api.request({ method: 'GET', path: '/products' }); return r.data.products.map(p => ({ id: p.id, name: p.name, price: p.price, stock: p.stock, inStock: p.inStock })); }"
    },
    "_meta": {
      "io.modelcontextprotocol/protocolVersion": "2026-07-28",
      "io.modelcontextprotocol/clientInfo": {
        "name": "postman-shopping-demo",
        "version": "1.0"
      },
      "io.modelcontextprotocol/clientCapabilities": {
        "elicitation": {
          "form": {}
        }
      }
    }
  }
}

